MATCH (l:Location)
CALL {
  WITH l
  MATCH (m:Member)-[:SUBSCRIBES_TO]->(p:MembershipPlan)-[:VALID_AT]->(l)
  CALL {
    WITH m
    MATCH (m)-[:BILLED]->(i:Invoice)-[:PAID_BY]->(pay:Payment)
    RETURN sum(pay.amount_paid) AS totalPaid
  }
  RETURN totalPaid
}
RETURN l.name AS location, totalPaid
ORDER BY totalPaid DESC

MATCH (cl:Classroom)-[:LOCATED_AT]->(c:Center)
WHERE c.max_capacity > 30 AND NOT EXISTS { (:Staff)-[:TEACHES_IN]->(cl) }
RETURN cl.name AS classroom, c.name AS center, c.max_capacity AS max_capacity

