MATCH (c:Child)-[:ENROLLED_IN]->(cl:Classroom)-[:LOCATED_AT]->(center:Center)
WHERE NOT EXISTS {
  MATCH (c)-[:HAS_ATTENDANCE]->(:AttendanceLog)<-[:CHECKED_IN]-(s:Staff)
  WHERE s.role = 'Director'
}
RETURN c.name, cl.room_number, center.name

