gold:
MATCH (g:Grant)
WHERE NOT EXISTS { MATCH (g)-[:SUBJECT_TO]->(:ComplianceRequirement) }
RETURN g.name AS grant_name

MATCH (a:Auditor)
CALL {
  WITH a
  MATCH (a)-[:CONDUCTED]->(af:AuditFinding)
  RETURN count(af) AS findings_conducted
}
CALL {
  WITH a
  MATCH (a)<-[:VERIFIED_BY]-(ra:RemediationAction {remediation_status: 'Completed'})
  RETURN count(ra) AS remediations_verified
}
RETURN a.name AS auditor, a.firm_name AS firm_name, findings_conducted, remediations_verified
ORDER BY findings_conducted DESC

